"""Typed campaign record parsing and publication/revision reconciliation."""
from common import Invalid, address, decimal, decode64, ident

TYPES = ('icmp', 'app')
RESULTS = {'icmp': ('echo', 'error', 'timeout'),
           'app': ('open', 'closed', 'timeout')}


def parse_record(values, context, lookup):
    """Parse one logical CSV data record into a typed campaign record.

    Raises Invalid for any logical record failure; callers report its index.
    """
    if type(values) is not list or len(values) != 14:
        raise Invalid('field count')
    (kind, rid, revision, published, op, lease, event, probe,
     target, responder, result, service, attempt, payload) = values
    if kind not in TYPES:
        raise Invalid('type')
    if not ident(rid):
        raise Invalid('id')
    rev = decimal(revision, 10**9)
    pub = decimal(published)
    if op == 'delete':
        if any(values[5:]):
            raise Invalid('delete fields')
        return {'identity': (kind, rid), 'type': kind, 'revision': rev,
                'published': pub, 'op': 'delete', 'content': ('delete',),
                'canary': False, 'lease': None, 'event': None, 'probe': None,
                'target': None, 'responder': None, 'result': None,
                'service': None, 'attempt': None, 'payload': None}
    if op != 'put':
        raise Invalid('op')
    leases = context['leases']
    if lease not in leases:
        raise Invalid('lease reference')
    ev = decimal(event)
    if not leases[lease]['start'] <= ev < leases[lease]['end'] or ev > pub:
        raise Invalid('event')
    tgt = address(target)
    canary = False
    if kind == 'icmp':
        hit = lookup.get((lease, probe))
        if hit is None or hit[0] != tgt:
            raise Invalid('probe or target')
        canary = hit[1]
        if result not in RESULTS['icmp']:
            raise Invalid('result')
        if result == 'timeout':
            if responder != '':
                raise Invalid('responder')
            resp = None
        else:
            resp = address(responder)
        if service != '' or attempt != '' or payload != '':
            raise Invalid('icmp fields')
        content = ('put', lease, ev, probe, tgt, resp, result, None, None, b'')
    else:
        if probe != '' or responder != '':
            raise Invalid('app fields')
        if service not in context['services']:
            raise Invalid('service reference')
        att = decimal(attempt, 10**6)
        if result not in RESULTS['app']:
            raise Invalid('result')
        body = decode64(payload, Invalid)
        if len(body) > 65536:
            raise Invalid('payload size')
        if result != 'open' and body:
            raise Invalid('payload')
        if context['services'][service] == 'tcp' and body:
            raise Invalid('payload')
        content = ('put', lease, ev, '', tgt, None, result, service, att, body)
    return {'identity': (kind, rid), 'type': kind, 'revision': rev,
            'published': pub, 'op': 'put', 'content': content,
            'canary': canary, 'lease': lease, 'event': ev, 'probe': probe,
            'target': tgt, 'responder': resp if kind == 'icmp' else None,
            'result': result, 'service': service if kind == 'app' else None,
            'attempt': att if kind == 'app' else None,
            'payload': body if kind == 'app' else b''}


class Ledger:
    """Publication/revision reconciliation of typed records at query times."""

    def __init__(self, records):
        self.records = records

    def at(self, time):
        """Return (live put rows, ledger counts) reconciled at time."""
        best = {}
        for rec in self.records:
            if rec['published'] > time:
                continue
            slot = best.get(rec['identity'])
            if slot is None:
                best[rec['identity']] = [rec['revision'], {rec['content']}, rec]
            elif rec['revision'] > slot[0]:
                best[rec['identity']] = [rec['revision'], {rec['content']}, rec]
            elif rec['revision'] == slot[0]:
                slot[1].add(rec['content'])
        live = []
        counts = {'live': 0, 'deleted': 0, 'conflict': 0}
        for revision, contents, rep in best.values():
            if len(contents) > 1:
                counts['conflict'] += 1
            elif rep['op'] == 'delete':
                counts['deleted'] += 1
            else:
                counts['live'] += 1
                live.append(rep)
        return live, counts
"""Revision-aware lease reconciliation and causal application census."""
from common import addresses
from ledger import Ledger
from protocols import signature


def analyze(context, low, rows, at):
    """Reconcile discovery roles and application evidence for one query."""
    leases = context['leases']
    services = context['services']
    icmp = {lid: [] for lid in leases}
    apps = {lid: [] for lid in leases}
    for rec in rows:
        (icmp if rec['type'] == 'icmp' else apps)[rec['lease']].append(rec)
    result = {}
    for lid, lease in leases.items():
        internal = set()
        external = set()
        witness = {}
        alias = False
        for rec in icmp[lid]:
            tgt, resp, event = rec['target'], rec['responder'], rec['event']
            if rec['canary']:
                if rec['result'] == 'echo' and resp == tgt:
                    alias = True
                continue
            if rec['result'] == 'echo' and resp == tgt:
                role, addr = 'internal', resp
                internal.add(addr)
            elif rec['result'] != 'timeout' and resp != tgt:
                role, addr = 'external', resp
                external.add(addr)
            else:
                continue
            key = (role, addr)
            if key not in witness or event < witness[key]:
                witness[key] = event
        conflicts = internal & external
        if not lease['start'] <= at < lease['end']:
            state = 'inactive'
        elif alias:
            state = 'alias'
        elif conflicts:
            state = 'conflict'
        else:
            state = 'usable'
        clean_i = internal if state == 'usable' else set()
        clean_e = external if state == 'usable' else set()
        if state == 'inactive':
            unresolved = set()
        else:
            unresolved = set(low[lid]) - clean_i - clean_e
        # Eligible application rows: usable lease, clean role, causal witness.
        groups = {}
        unbound = 0
        for rec in apps[lid]:
            tgt = rec['target']
            if state == 'usable':
                role = 'internal' if tgt in internal else (
                    'external' if tgt in external else None)
                if role is not None:
                    seen = witness.get((role, tgt))
                    if seen is not None and seen <= rec['event']:
                        groups.setdefault((tgt, rec['service']), []).append(rec)
                        continue
            unbound += 1
        status = {}
        errors = {sid: 0 for sid in services}
        for (tgt, sid), grows in groups.items():
            latest = max(r['attempt'] for r in grows)
            top = [r for r in grows if r['attempt'] == latest]
            kind = services[sid]
            sigs = []
            malformed = 0
            for rec in top:
                if rec['result'] == 'open':
                    parsed = signature(kind, rec['payload'])
                    sigs.append(parsed)
                    if parsed is None:
                        malformed += 1
            errors[sid] += malformed
            if all(r['result'] == 'closed' for r in top):
                status[(tgt, sid)] = 'closed'
            elif all(r['result'] == 'open' for r in top) and not malformed \
                    and all(s == sigs[0] for s in sigs):
                status[(tgt, sid)] = 'open'
            else:
                status[(tgt, sid)] = 'unknown'
        result[lid] = {'state': state, 'alias': alias,
                       'conflicts': conflicts if state != 'inactive' else set(),
                       'internal': clean_i, 'external': clean_e,
                       'unresolved': unresolved, 'status': status,
                       'errors': errors, 'unbound': unbound}
    return result


def render(context, analysis):
    """Shape one snapshot: ledger-free view keys in protocol order."""
    services = context['services']
    leases_out = []
    unbound = 0
    for lid in sorted(context['leases']):
        entry = analysis[lid]
        unbound += entry['unbound']
        status = entry['status']
        services_out = []
        for sid in sorted(services):
            internal_open = addresses([a for a in entry['internal']
                                       if status.get((a, sid)) == 'open'])
            internal_closed = addresses([a for a in entry['internal']
                                         if status.get((a, sid)) == 'closed'])
            external_open = addresses([a for a in entry['external']
                                       if status.get((a, sid)) == 'open'])
            external_closed = addresses([a for a in entry['external']
                                         if status.get((a, sid)) == 'closed'])
            external = entry['external']
            internal_only = internal_open if (external and all(
                status.get((a, sid)) == 'closed' for a in external)) else []
            services_out.append({'id': sid,
                                 'internal_open': internal_open,
                                 'internal_closed': internal_closed,
                                 'external_open': external_open,
                                 'external_closed': external_closed,
                                 'internal_only': internal_only,
                                 'protocol_errors': entry['errors'].get(sid, 0)})
        leases_out.append({'lease': lid, 'state': entry['state'],
                           'conflicts': addresses(entry['conflicts']),
                           'internal': addresses(entry['internal']),
                           'external': addresses(entry['external']),
                           'unresolved': addresses(entry['unresolved']),
                           'services': services_out})
    return leases_out, unbound


def build(context, records, low):
    """Snapshots in query order plus frozen per-request activity flags."""
    ledger = Ledger(records)
    snapshots = []
    analyses = {}
    for at in context['queries']:
        rows, counts = ledger.at(at)
        analysis = analyze(context, low, rows, at)
        analyses[at] = analysis
        leases_out, unbound = render(context, analysis)
        snapshots.append({'at': at, 'ledger': counts,
                          'unbound_applications': unbound,
                          'leases': leases_out})
    active = {}
    for rid, req in context['requests'].items():
        entry = analyses[req['at']][req['lease']]
        ok = entry['state'] == 'usable' and req['address'] in entry['internal']
        active[rid] = bool(ok and entry['status'].get(
            (req['address'], req['service']), 'unknown') == 'unknown')
    return snapshots, active
